const ROOT_SID = 'root-session-d2-s6'
const OWNED_SID = 'root-session-d2-owned'
const FOREIGN_SID = 'root-session-foreign-d2'

/** Extract the typed error part of a resolved error envelope (asserts the invariant-7 shape). */
function errorOf(response: RemoteResponse): Record<string, unknown> {
  if (response.ok) throw new Error('D2-S6 guard: expected an error result')
  return response.error as unknown as Record<string, unknown>
}

/** Extract the success data part of a resolved success envelope. */
function dataOf(response: RemoteResponse): Record<string, unknown> {
  if (!response.ok) throw new Error('D2-S6 guard: expected a success result')
  return response.value.data as Record<string, unknown>
}

/** The trip-wire repositories: ANY access is a test failure. */
function tripWireRepositories(): { repos: TeamDomainRepositories; touched: string[] } {
  const touched: string[] = []
  const trip = (name: string): never => {
    touched.push(name)
    throw new Error(`D2-S6 guard: team.ensureRootLive must not touch repositories.${name}`)
  }
  const repos = {
    teamSessions: { list: () => trip('teamSessions.list'), get: () => trip('teamSessions.get'), put: () => trip('teamSessions.put') },
    memberInstances: { list: () => trip('memberInstances.list'), get: () => trip('memberInstances.get'), put: () => trip('memberInstances.put') },
    sessionBindings: { get: () => trip('sessionBindings.get'), put: () => trip('sessionBindings.put'), listByKind: () => trip('sessionBindings.listByKind') },
    schemaMeta: { listStamps: () => trip('schemaMeta.listStamps'), size: 0 },
    overrides: { list: () => trip('overrides.list') },
    compatibility: { get: () => trip('compatibility.get') },
    operations: { list: () => trip('operations.list') },
    ledger: { list: () => trip('ledger.list'), count: () => trip('ledger.count') },
  } as unknown as TeamDomainRepositories
  return { repos, touched }
}

/** The scripted glue port: records the addressed roots, answers per the given script. */
function makeEnsurePort(
  script: (rootSessionId: string) => Promise<void> | void,
): {
  ensure: (rootSessionId: string) => Promise<void>
  calls: string[]
} {
  const calls: string[] = []
  const ensure = async (rootSessionId: string): Promise<void> => {
    calls.push(rootSessionId)
    await script(rootSessionId)
  }
  return { ensure, calls }
}

/** Build the production ports over a minimal (but trip-wired) options object. */
function makePorts(options: {
  readonly ensure?: (rootSessionId: string) => Promise<void>
  readonly isOwnedRoot?: (teamSessionId: string) => boolean
  readonly prepareOrdinaryOpen?: (rootSessionId: string) => Promise<void> | void
}): { ports: ReturnType<typeof createS6RemotePorts>; touched: string[] } {
  const { repos, touched } = tripWireRepositories()
  const opts = {
    rootSessionId: ROOT_SID,
    repositories: repos,
    ...(options.ensure === undefined ? {} : { ensureRootLive: options.ensure }),
    ...(options.isOwnedRoot === undefined ? {} : { isOwnedRoot: options.isOwnedRoot }),
    ...(options.prepareOrdinaryOpen === undefined
      ? {}
      : { prepareOrdinaryOpen: options.prepareOrdinaryOpen }),
  } as unknown as S6RemoteOptions
  const ports = createS6RemotePorts(opts)
  return { ports, touched }
}

// Module level (top-level await): drive the REAL production dispatcher
// over the fake options and capture every scenario result.
const D2 = await (async () => {
  const noPrincipal: ServerPrincipalDerivation = () => {
    throw new Error('D2-S6 guard: principal derivation must not run for this method')
  }
  // (a) SUCCESS — the bound root, the glue port resolves.
  const successPort = makeEnsurePort(() => undefined)
  const success = makePorts({ ensure: successPort.ensure })
  const dispatchSuccess = createS6RemoteDispatcher(success.ports, noPrincipal)
  const successResponse = await dispatchSuccess('team.ensureRootLive', {
    version: REMOTE_CONTRACT_VERSION_V3,
    params: { teamSessionId: ROOT_SID },
  })

  // (b) SUCCESS — a DURABLY OWNED root (P9-S8, not the bound root).
  const ownedPort = makeEnsurePort(() => undefined)
  const owned = makePorts({
    ensure: ownedPort.ensure,
    isOwnedRoot: (sid) => sid === OWNED_SID,
  })
  const dispatchOwned = createS6RemoteDispatcher(owned.ports, noPrincipal)
  const ownedResponse = await dispatchOwned('team.ensureRootLive', {
    version: REMOTE_CONTRACT_VERSION_V3,
    params: { teamSessionId: OWNED_SID },
  })

  // (c) GUARD — a foreign/unknown root fails closed BEFORE the port runs.
  const foreignPort = makeEnsurePort(() => undefined)
  const foreign = makePorts({ ensure: foreignPort.ensure })
  const dispatchForeign = createS6RemoteDispatcher(foreign.ports, noPrincipal)
  const foreignResponse = await dispatchForeign('team.ensureRootLive', {
    version: REMOTE_CONTRACT_VERSION_V3,
    params: { teamSessionId: FOREIGN_SID },
  })

  // (d) FAIL-CLOSED — the host wiring is absent (no ensureRootLive option).
  const absent = makePorts({})
  const dispatchAbsent = createS6RemoteDispatcher(absent.ports, noPrincipal)
  const absentResponse = await dispatchAbsent('team.ensureRootLive', {
    version: REMOTE_CONTRACT_VERSION_V3,
    params: { teamSessionId: ROOT_SID },
  })

  // (e) TYPED — already live OUTSIDE the Team glue: the registry
  // collision rejection (core/agent enter(), the upstream's authoritative
  // collision boundary — a second agent under one session id is
  // structurally impossible, A3 Q1).
  const outsidePort = makeEnsurePort(() => {
    throw new Error(`agent "${ROOT_SID}" is already registered`)
  })
  const outside = makePorts({ ensure: outsidePort.ensure })
  const dispatchOutside = createS6RemoteDispatcher(outside.ports, noPrincipal)
  const outsideResponse = await dispatchOutside('team.ensureRootLive', {
    version: REMOTE_CONTRACT_VERSION_V3,
    params: { teamSessionId: ROOT_SID },
  })

  // (f) TYPED — no durable session artifact: the glue's own
  // "neither live nor durable" rejection (agent-bindings ensureLiveAgent).
  const noDurablePort = makeEnsurePort(() => {
    throw new Error(`p6t6: session '${ROOT_SID}' is neither live nor durable — no agent to execute a tool on`)
  })
  const noDurable = makePorts({ ensure: noDurablePort.ensure })
  const dispatchNoDurable = createS6RemoteDispatcher(noDurable.ports, noPrincipal)
  const noDurableResponse = await dispatchNoDurable('team.ensureRootLive', {
    version: REMOTE_CONTRACT_VERSION_V3,
    params: { teamSessionId: ROOT_SID },
  })

  // (g) TYPED — every other glue failure: the start path blew up.
  const startFailedPort = makeEnsurePort(() => {
    throw new Error('model provider exploded mid-resume')
  })
  const startFailed = makePorts({ ensure: startFailedPort.ensure })
  const dispatchStartFailed = createS6RemoteDispatcher(startFailed.ports, noPrincipal)
  const startFailedResponse = await dispatchStartFailed('team.ensureRootLive', {
    version: REMOTE_CONTRACT_VERSION_V3,
    params: { teamSessionId: ROOT_SID },
  })

  // ── C1 (restart-recovery, guide §13.4): the writer-held mapping +
  // the team.prepareOrdinaryOpen port (R1–R5) ──

  // (h) R1a — the TYPED writer-held marker (the 0.1.7
  // SessionAlreadyOwnedError's name): the ensureRootLive rejection maps
  // to TEAM_REMOTE_TEAM_ROOT_LIVE_OUTSIDE_TEAM (the writer's ordinary
  // session is live OUTSIDE the Team glue — refuse, never adopt).
  const writerHeldPort = makeEnsurePort(() => {
    throw Object.assign(
      new Error(`session "${ROOT_SID}" is already owned by an active write handle`),
      { name: 'SessionAlreadyOwnedError' },
    )
  })
  const writerHeld = makePorts({ ensure: writerHeldPort.ensure })
  const dispatchWriterHeld = createS6RemoteDispatcher(writerHeld.ports, noPrincipal)
  const writerHeldResponse = await dispatchWriterHeld('team.ensureRootLive', {
    version: REMOTE_CONTRACT_VERSION_V3,
    params: { teamSessionId: ROOT_SID },
  })

  // (i) R1b — the STRUCTURED remote code (the api/session-controller
  // 'session/writer-held' code on a plain Error): the SAME mapping.
  const writerHeldCodePort = makeEnsurePort(() => {
    throw Object.assign(new Error('the ordinary write handle is active'), {
      code: 'session/writer-held',
    })
  })
  const writerHeldCode = makePorts({ ensure: writerHeldCodePort.ensure })
  const dispatchWriterHeldCode = createS6RemoteDispatcher(writerHeldCode.ports, noPrincipal)
  const writerHeldCodeResponse = await dispatchWriterHeldCode('team.ensureRootLive', {
    version: REMOTE_CONTRACT_VERSION_V3,
    params: { teamSessionId: ROOT_SID },
  })

  // (j) R2 — the port-level team.prepareOrdinaryOpen: the BOUND root and
  // a DURABLY OWNED root (P9-S8) both arm the one-shot permit and
  // resolve the closed shape `{ rootSessionId, permitted: true }` — the
  // armer is called exactly once with the addressed root.
  const armerBound: string[] = []
  const boundArmed = makePorts({
    prepareOrdinaryOpen: (sid) => {
      armerBound.push(sid)
    },
  })
  const boundArmedResult = await boundArmed.ports.teamPrepareOrdinaryOpen.prepareOrdinaryOpen(
    ROOT_SID,
  )
  const armerOwned: string[] = []
  const ownedArmed = makePorts({
    isOwnedRoot: (sid) => sid === OWNED_SID,
    prepareOrdinaryOpen: (sid) => {
      armerOwned.push(sid)
    },
  })
  const ownedArmedResult = await ownedArmed.ports.teamPrepareOrdinaryOpen.prepareOrdinaryOpen(
    OWNED_SID,
  )

  // (k) R3 — a FOREIGN/unknown root fails closed BEFORE any arming
  // (assertBoundRoot first — the armer is never called).
  const armerForeign: string[] = []
  const foreignArmed = makePorts({
    prepareOrdinaryOpen: (sid) => {
      armerForeign.push(sid)
    },
  })
  const foreignArmedError = await foreignArmed.ports.teamPrepareOrdinaryOpen
    .prepareOrdinaryOpen(FOREIGN_SID)
    .then(
      () => {
        throw new Error('D2-S6 guard: expected the foreign root to fail closed')
      },
      (error: unknown) => error,
    )

  // (l) R4 — arming the permit performs NO Team ensure (the ordinary
  // compatibility is a process-local permit, not a Team activation):
  // the recording ensureRootLive option is never called.
  const r4EnsurePort = makeEnsurePort(() => undefined)
  const r4Armer: string[] = []
  const r4 = makePorts({
    ensure: r4EnsurePort.ensure,
    prepareOrdinaryOpen: (sid) => {
      r4Armer.push(sid)
    },
  })
  const r4Result = await r4.ports.teamPrepareOrdinaryOpen.prepareOrdinaryOpen(ROOT_SID)

  // (m) R5 — the READ-ONLY contract: arming the permit performs no
  // repository access of any kind (the trip-wire was never touched).
  const r5Armer: string[] = []
  const r5 = makePorts({
    prepareOrdinaryOpen: (sid) => {
      r5Armer.push(sid)
    },
  })
  const r5Result = await r5.ports.teamPrepareOrdinaryOpen.prepareOrdinaryOpen(ROOT_SID)

  // (n) R4 complement — an ABSENT armer (no fence wired) fails closed
  // typed BEFORE arming anything.
  const absentArmer = makePorts({})
  const absentArmerError = await absentArmer.ports.teamPrepareOrdinaryOpen
    .prepareOrdinaryOpen(ROOT_SID)
    .then(
      () => {
        throw new Error('D2-S6 guard: expected the absent armer to fail closed')
      },
      (error: unknown) => error,
    )

  return {
    successResponse,
    successCalls: successPort.calls,
    successTouched: success.touched,
    ownedResponse,
    ownedCalls: ownedPort.calls,
    foreignResponse,
    foreignCalls: foreignPort.calls,
    absentResponse,
    outsideResponse,
    noDurableResponse,
    startFailedResponse,
    writerHeldResponse,
    writerHeldCodeResponse,
    boundArmedResult,
    armerBoundCalls: armerBound,
    ownedArmedResult,
    armerOwnedCalls: armerOwned,
    foreignArmedError,
    armerForeignCalls: armerForeign,
    r4Result,
    r4ArmerCalls: r4Armer,
    r4EnsureCalls: r4EnsurePort.calls,
    r5Result,
    r5Touched: r5.touched,
    absentArmerError,
  }
})()

// ---------------------------------------------------------------------------
// R6 (supplement round guide §4.4) — the PRODUCTION-ROOT wiring level
// ---------------------------------------------------------------------------
// R2–R5 above drive the S6 PORT over scripted options. R6 drives the
// same method through the REAL production root (createTeamProductionRoot
// — the SAME factory the host entry calls — over the SAME installed
// registration seam the production host exposes on
// `root.seams.remoteHandlerRegistration`): the root.ts CONDITIONAL
// SPREAD is the wiring under test — the S6 `prepareOrdinaryOpen` port is
// exposed IFF the live bundle exposes `allowOrdinaryActivationOnce`
// (the fence's `permitOrdinaryOnce` passthrough). The pre-round literal
// form `prepareOrdinaryOpen: (sid) => live.allowOrdinaryActivationOnce?.(sid)`
// was a FAKE SUCCESS: a world without the armer armed nothing, yet the
// call returned `{ permitted: true }`.
//
//   R6a — the NO-ARMER root (the live bundle has no
//         allowOrdinaryActivationOnce): the drive fails closed with the
//         typed TEAM_REMOTE_TEAM_ORDINARY_OPEN_PORT_UNAVAILABLE — NEVER
//         a success envelope (the fake success is gone).
//   R6b — the SAME root wiring with the armer present (the bundle
//         exposes it): the port is live, the permit arms exactly once,
//         the closed success shape resolves (a regression guard against
//         an over-omitted spread — the spread's true branch is pinned
//         at the root level too).

const R6 = await (async () => {
  const R6_NOW = '2026-08-31T00:00:00.000Z'
  // A4-PR7 §7.4 (lane B-runtime-semantics-A): this fixture document rides the
  // supported version, and the two envelope documents that version REQUIRES are
  // declared — in their zero form `rules: []`, which is a POSITION: on the
  // expansion plane a no-match answers `no-authority` (the document claims no
  // expansion authority for its Leader), on the approval plane a no-match is
  // identity (it removes no rung). The zeros are honest here rather than
  // convenient: this world is built root-direct, and the only production producer
  // of `permissionAuthorityCeiling` is the plugin host, so no ceiling reader ever
  // consults these documents. (The same disposition covers every document below.)
  /** The R6 row blueprint (own id; structure mirrors the t12b1 fixture). */
  const DOC_R6 = [
    '---',
    'schemaVersion: 3',
    'blueprintId: D2-R6-BP',
    'revision: "1"',
    'leader:',
    '  templateId: leader',
    '  persona: You lead the D2-R6 team.',
    'members:',
    '  - templateId: worker',
    '    displayName: Worker',
    '    persona: You do the D2-R6 work.',
    'requirements:',
    '  - domain: tool',
    '    name: web',
    '    optional: true',
    'teamEnvelope:',
    '  allow:',
    '    - assign-task',
    '    - create-member',
    '    - send-message',
    '    - report-progress',
    '    - archive-member',
    '    - restore-member',
    '  deny:',
    '    - delete-team',
    'memberEnvelopes:',
    '  - templateId: worker',
    '    envelope:',
    '      allow:',
    '        - send-message',
    '        - report-progress',
    '      deny: []',
    'policyStates:',
    '  - id: default',
    '    description: The D2-R6 default state.',
    'quotas:',
    '    team:',
    '      maxInstances: 12',
    '      maxConcurrent: 12',
    '    members:',
    '      maxInstances: 4',
    '      maxConcurrent: 4',
    'metadata: {}',
    'permissionMutationEnvelope:',
    '  rules: []',
    'teamHardEnvelope:',
    '  rules: []',
    '---',
  ].join('\n')
  /** The bound snapshot ref of DOC_R6 (the strong parse supplies the hash). */
  const parsedR6 = parseBlueprint(DOC_R6)
  const REF_R6: BlueprintSnapshotRef = createBlueprintSnapshotRef({
    blueprintId: parseBlueprintId(String(parsedR6.blueprintId)),
    revision: parseBlueprintRevision(String(parsedR6.revision)),
    contentHash: parseBlueprintContentHash(String(parsedR6.contentHash)),
  })

  /**
   * One R6 root world: a fresh domain seeded with the root's TeamSession
   * row (the bound-root guard PASSES — the drive reaches the armer
   * check, not the foreign guard), the stub glue bundle (optionally
   * extended with the armer), the production root factory, and the
   * INSTALLED registration seam captured through the ConnectionLike
   * double (the p8s6-remote-commands pattern — the dispatcher is the
   * production S6 dispatcher).
   */
  // eslint-disable-next-line @typescript-eslint/no-explicit-any -- dynamic service surface (test double), untyped by design
  async function buildWorld(scratch: string, armer?: (rootSessionId: string) => void): Promise<any> {
    const seam = new FileStorageSeam(scratch)
    const domain = await createTeamDomain(seam)
    await domain.repositories.teamSessions.put(
      createTeamSessionRecord({
        rootSessionId: parseRootSessionId(ROOT_SID),
        blueprint: REF_R6,
        createdAt: R6_NOW,
        generation: 1,
      }),
    )
    const config: TeamPluginConfig = {
      bootPhase: 'create',
      rootSessionId: ROOT_SID,
      blueprintSource: DOC_R6,
      generation: 1,
      defaultWorkspace: 'C:/agent-team/work/d2-r6',
      seedMembers: [],
      staticModel: { provider: 'd2-r6', model: 'd2-r6-model-v1' },
      deniedSelection: null,
      mcpServer: null,
      environmentFacts: [],
      externalPolicyFacts: { hard: {}, capabilityExists: {} },
    }
    const teamToolsRef = { current: undefined }
    const stub = createStubBindings({ config, teamToolsRef, domain })
    // eslint-disable-next-line @typescript-eslint/no-explicit-any -- untyped stub glue surface, extended only for R6b
    const live: any = armer === undefined ? stub : { ...stub, allowOrdinaryActivationOnce: armer }
    const unused = (): never => {
      throw new Error('R6 guard: legacy inspect is unused in this world')
    }
    const root = createTeamProductionRoot({
      config,
      domain,
      storageSeam: seam,
      live,
      now: () => R6_NOW,
      teamToolsRef,
      controlServiceRef: { current: undefined },
      legacyInspect: unused as never,
    })
    // eslint-disable-next-line @typescript-eslint/no-explicit-any -- dynamic service surface (test double), untyped by design
    let dispatcher: ((endpoint: string, payload: unknown) => Promise<RemoteResponse>) | null = null
    root.seams.remoteHandlerRegistration.current()({
      rpc: {
        handle: (_channel: string, handler: unknown) => {
          // eslint-disable-next-line @typescript-eslint/no-explicit-any -- dynamic service surface (test double), untyped by design
          dispatcher = handler as (endpoint: string, payload: unknown) => Promise<RemoteResponse>
          return () => {}
        },
      },
    })
    if (dispatcher === null) throw new Error('R6 guard: registration never registered a dispatcher')
    return { root, dispatcher }
  }

  // R6a — the NO-ARMER production root (the stub bundle exposes no
  // allowOrdinaryActivationOnce): the conditional spread omits the S6
  // port; the drive must fail closed typed — never the pre-round fake
  // `{ permitted: true }`.
  const scratchA = scratchDir('d2-r6a-no-armer')
  const worldA = await buildWorld(scratchA)
  // team.prepareOrdinaryOpen is a v5-only wire method (the frozen catalog
  // learned it in the Commit-3 contract extension): the wire drive uses
  // the v5 envelope.
  const r6aResponse = await worldA.dispatcher('team.prepareOrdinaryOpen', {
    version: REMOTE_CONTRACT_VERSION_V5,
    params: { teamSessionId: ROOT_SID },
  })
  await worldA.root.close()
  destroyDir(scratchA)

  // R6b — the SAME root wiring with the armer present (the spread's
  // true branch): the port is live; the permit arms exactly once.
  const armerCalls: string[] = []
  const scratchB = scratchDir('d2-r6b-armer')
  const worldB = await buildWorld(scratchB, (sid) => {
    armerCalls.push(sid)
  })
  const r6bResponse = await worldB.dispatcher('team.prepareOrdinaryOpen', {
    version: REMOTE_CONTRACT_VERSION_V5,
    params: { teamSessionId: ROOT_SID },
  })
  await worldB.root.close()
  destroyDir(scratchB)

  return { r6aResponse, r6bResponse, armerCalls }
})()

// ---------------------------------------------------------------------------
// Assertions (synchronous `it` bodies over the captured results)
// ---------------------------------------------------------------------------

describe('D2 (S6 host handler): team.ensureRootLive success', () => {
  it('an owned durable root: the port is called exactly once with the rootSessionId and the closed v3 shape resolves', () => {
    expect(D2.successResponse.ok).toBe(true)
    if (!D2.successResponse.ok) throw new Error('D2-S6 guard: expected success')
    expect(D2.successResponse.value.provenance.contractVersion).toBe(REMOTE_CONTRACT_VERSION_V3)
    expect(D2.successResponse.value.provenance.method).toBe('team.ensureRootLive')
    const data = dataOf(D2.successResponse)
    expect(Object.keys(data)).toEqual(['rootSessionId', 'mode', 'live'])
    expect(data).toEqual({ rootSessionId: ROOT_SID, mode: 'team', live: true })
  })

  it('the glue port is called exactly once with the addressed bound root', () => {
    expect(D2.successCalls).toEqual([ROOT_SID])
  })

  it('the READ-ONLY contract: no repository access of any kind (the trip-wire was never touched)', () => {
    expect(D2.successTouched).toEqual([])
  })

  it('a durably OWNED root (P9-S8, not the bound root) is accepted and ensured', () => {
    expect(D2.ownedResponse.ok).toBe(true)
    if (D2.ownedResponse.ok) {
      expect(dataOf(D2.ownedResponse)).toEqual({ rootSessionId: OWNED_SID, mode: 'team', live: true })
    }
    expect(D2.ownedCalls).toEqual([OWNED_SID])
  })
})

describe('D2 (S6 host handler): the bound-root guard (TEAM-SCOPED, fail-closed)', () => {
  it('a FOREIGN/unknown root fails closed TEAM_REMOTE_FOREIGN_TEAM BEFORE the port runs', () => {
    const error = errorOf(D2.foreignResponse)
    expect(error['code']).toBe('TEAM_REMOTE_FOREIGN_TEAM')
    expect(String(error['message'])).toContain(`'${FOREIGN_SID}'`)
    expect(String(error['message'])).toContain(`bound root '${ROOT_SID}'`)
  })

  it('the glue port was NEVER called for the foreign root', () => {
    expect(D2.foreignCalls).toEqual([])
  })
})

describe('D2 (S6 host handler): the typed failure vocabulary (A3 Q2)', () => {
  it('an ABSENT ensureRootLive option → typed TEAM_REMOTE_TEAM_ROOT_LIVE_PORT_UNAVAILABLE (fail closed, the D-3 discipline mirrored)', () => {
    const error = errorOf(D2.absentResponse)
    expect(error['code']).toBe(S6_REMOTE_ERROR_CODES.TEAM_ROOT_LIVE_PORT_UNAVAILABLE)
    expect(error['code']).toBe('TEAM_REMOTE_TEAM_ROOT_LIVE_PORT_UNAVAILABLE')
    const details = error['details'] as Record<string, unknown>
    // invariant 4b pass-through: the source identity rides under cause
    expect(details['reason']).toBe('domain-error')
    expect((details['cause'] as Record<string, unknown>)['code']).toBe('TEAM_REMOTE_TEAM_ROOT_LIVE_PORT_UNAVAILABLE')
    expect(String(error['message'])).toContain('does not provide the ensureRootLive port')
  })

  it('the registry collision rejection (already live OUTSIDE the Team glue) → TEAM_REMOTE_TEAM_ROOT_LIVE_OUTSIDE_TEAM (never a silent adoption)', () => {
    const error = errorOf(D2.outsideResponse)
    expect(error['code']).toBe(S6_REMOTE_ERROR_CODES.TEAM_ROOT_LIVE_OUTSIDE_TEAM)
    expect(error['code']).toBe('TEAM_REMOTE_TEAM_ROOT_LIVE_OUTSIDE_TEAM')
    const details = error['details'] as Record<string, unknown>
    expect(details['reason']).toBe('domain-error')
    expect((details['cause'] as Record<string, unknown>)['code']).toBe('TEAM_REMOTE_TEAM_ROOT_LIVE_OUTSIDE_TEAM')
    expect(String(error['message'])).toContain(`'${ROOT_SID}'`)
    expect(String(error['message'])).toContain('already live outside the Team glue')
  })

